"""Drawings the SOLIDWORKS way on TechDraw.

* FreeWorks sheet formats (Resources/Templates, generated by tools/make_templates.py) become
  TechDraw's default templates; ISO sheets use first-angle projection, ANSI sheets third-angle.
* Title block: MATERIAL, WEIGHT and DWG NO. are filled from the part shown on the sheet (like
  SOLIDWORKS' linked custom properties); title / author / date / scale / sheet use TechDraw autofill.
* Standard 3 View and Model View (named orientations) commands.
"""
import os

import FreeCAD as App

from . import MOD_DIR, log, params

TEMPLATE_DIR = os.path.join(MOD_DIR, "Resources", "Templates")
DEFAULT_ISO = "A3_ISO.svg"
DEFAULT_ANSI = "B_ANSI_Landscape.svg"
TD_FILES = "User parameter:BaseApp/Preferences/Mod/TechDraw/Files"
ORIENT = {   # SOLIDWORKS name -> (Direction, XDirection); FreeWorks/FreeCAD: Front looks along +Y
    "Front": ((0, -1, 0), (1, 0, 0)), "Back": ((0, 1, 0), (-1, 0, 0)),
    "Top": ((0, 0, 1), (1, 0, 0)), "Bottom": ((0, 0, -1), (1, 0, 0)),
    "Right": ((1, 0, 0), (0, 1, 0)), "Left": ((-1, 0, 0), (0, -1, 0)),
    "Isometric": ((1, -1, 1), (1, 1, 0)), "Dimetric": ((0.5, -1, 0.66), (1, 0.5, 0)),
    "Trimetric": ((0.75, -1, 0.85), (1, 0.75, 0)),
}


def templates():
    return sorted(f for f in os.listdir(TEMPLATE_DIR) if f.endswith(".svg")) if os.path.isdir(TEMPLATE_DIR) else []


def register():
    """Use FreeWorks sheet formats as TechDraw's default (unless the user picked another folder)."""
    g = App.ParamGet(TD_FILES)
    cur = g.GetString("TemplateDir", "")
    fw = params()
    if not cur or cur == fw.GetString("RegisteredTemplateDir", "") or not os.path.isdir(cur):
        g.SetString("TemplateDir", TEMPLATE_DIR)
        default = DEFAULT_ANSI if fw.GetString("MassUnits", "MMGS") == "IPS" else DEFAULT_ISO
        g.SetString("TemplateFile", os.path.join(TEMPLATE_DIR, default))
        fw.SetString("RegisteredTemplateDir", TEMPLATE_DIR)


def is_freeworks_template(page):
    t = getattr(page, "Template", None)
    f = getattr(t, "Template", "") if t is not None else ""
    return bool(f) and os.path.basename(f) in templates()


def projection_for(page):
    t = getattr(page, "Template", None)
    f = os.path.basename(getattr(t, "Template", "") or "")
    return "Third angle" if "ANSI" in f else "First angle"


def _source(page):
    for v in page.Views:
        src = getattr(v, "Source", None) or []
        if v.isDerivedFrom("TechDraw::DrawProjGroup"):
            src = v.Source
        for s in src:
            return s
    return None


_filled = {}


def fill_title_block(page):
    """MATERIAL / WEIGHT / DWG NO. from the part on the sheet. Returns True if something changed."""
    t = getattr(page, "Template", None)
    if t is None or not hasattr(t, "EditableTexts"):
        return False
    src = _source(page)
    if src is None:
        return False
    from . import materials, massprops
    et = dict(t.EditableTexts)
    want = {}
    bodies = materials._bodies_in(src) or [src]
    mats = sorted({materials.material_of(b)[0] for b in bodies})
    try:
        key = (src.Document.Name, src.Name, tuple(mats), src.Shape.hashCode(), tuple(sorted(et.items())))
    except Exception:
        key = None
    ck = (page.Document.Name, page.Name)
    if key is not None and _filled.get(ck) == key:
        return False                                  # nothing changed since the last fill
    if "material" in et:
        want["material"] = mats[0] if len(mats) == 1 else "<multiple>"
    if "weight" in et:
        try:
            items = []
            massprops._walk(src, src, "", None, True, items)
            res = massprops.compute(items)
            if res:
                want["weight"] = "%.2f g" % res["mass"] if res["mass"] < 1000 else "%.3f kg" % (res["mass"] / 1000.0)
        except Exception as e:
            log("title block weight: %s" % e)
    if "drawing_number" in et and et["drawing_number"].strip() in ("", "\u00a0"):
        want["drawing_number"] = src.Document.Label
    if "title" in et and et["title"].strip() in ("", "\u00a0", page.Document.Label):
        want["title"] = src.Document.Label
    changed = {k: v for k, v in want.items() if et.get(k) != v}
    if changed:
        et.update(changed)
        t.EditableTexts = et
    if key is not None:
        _filled[ck] = key[:4] + (tuple(sorted(et.items())),)
    return bool(changed)


def sweep(doc):
    for p in doc.Objects:
        if p.isDerivedFrom("TechDraw::DrawPage"):
            try:
                if is_freeworks_template(p) and hasattr(p, "ProjectionType") and p.ProjectionType != projection_for(p) \
                        and not getattr(p, "FW_ProjectionSet", False):
                    p.ProjectionType = projection_for(p)
                    p.addProperty("App::PropertyBool", "FW_ProjectionSet", "FreeWorks", "projection set from sheet format")
                    p.FW_ProjectionSet = True
                fill_title_block(p)
            except Exception as e:
                log("drawing sweep: %s" % e)


class _Observer:
    def slotRecomputedDocument(self, doc):
        if any(o.isDerivedFrom("TechDraw::DrawPage") for o in doc.Objects):
            sweep(doc)


_obs = {"o": None}


def install():
    if _obs["o"] is None:
        from . import harden
        _obs["o"] = harden(_Observer)()
        App.addDocumentObserver(_obs["o"])


# ------------------------------------------------------------------ views
def page_of(doc=None):
    doc = doc or App.ActiveDocument
    if doc is None:
        return None
    try:
        import FreeCADGui as Gui
        v = Gui.ActiveDocument.ActiveView
        if hasattr(v, "getPage"):
            return v.getPage()
    except Exception:
        pass
    pages = [o for o in doc.Objects if o.isDerivedFrom("TechDraw::DrawPage")]
    return pages[0] if pages else None


def _place(page, view, fx, fy):
    try:
        w, h = float(page.Template.Width), float(page.Template.Height)
    except Exception:
        w, h = 420.0, 297.0
    view.X, view.Y = w * fx, h * fy


STD_SCALES = [10, 5, 2, 1, 0.5, 0.2, 0.1, 0.05, 0.02, 0.01]


def _bbox(source):
    import Part
    try:
        return Part.getShape(source).BoundBox
    except Exception:
        return source.Shape.BoundBox


def standard_3view(page, source):
    """Front, Top and Right (SOLIDWORKS Standard 3 View), laid out in the sheet's projection (ISO:
    first angle - Top below, Right to the left; ANSI: third angle - Top above, Right to the right).
    Three DrawViewPart views at one standard scale (scripted TechDraw projection groups don't lay
    out reliably in FreeCAD 1.1.4)."""
    doc = page.Document
    bb = _bbox(source)
    try:
        W, H = float(page.Template.Width), float(page.Template.Height)
    except Exception:
        W, H = 420.0, 297.0
    gap = 20.0
    tw, th = bb.XLength + bb.YLength, bb.ZLength + bb.YLength
    avail_w, avail_h = (W - 40) * 0.62, (H - 80) * 0.85
    scale = next((sc for sc in STD_SCALES if tw * sc + gap <= avail_w and th * sc + gap <= avail_h), STD_SCALES[-1])
    first = projection_for(page) == "First angle"
    fw, fh, ry = bb.XLength * scale, bb.ZLength * scale, bb.YLength * scale
    cx = W * 0.40
    cy = H * 0.58
    dx = fw / 2 + gap + ry / 2
    dy = fh / 2 + gap + ry / 2
    pos = {"Front": (cx, cy), "Top": (cx, cy - dy if first else cy + dy), "Right": (cx - dx if first else cx + dx, cy)}
    views = []
    for name in ("Front", "Top", "Right"):
        d, x = ORIENT[name]
        v = doc.addObject("TechDraw::DrawViewPart", "View")
        page.addView(v)
        v.Source = [source]
        v.Direction = App.Vector(*d)
        v.XDirection = App.Vector(*x)
        try:
            v.ScaleType = "Custom"
            v.Scale = scale
        except Exception:
            pass
        v.Label = "Drawing View%d" % (len(page.Views))
        v.X, v.Y = pos[name]
        try:
            v.addProperty("App::PropertyString", "StandardView", "FreeWorks", "Standard 3 View role")
            v.StandardView = name
        except Exception:
            pass
        views.append(v)
    doc.recompute()
    return views


def model_view(page, source, orientation="Isometric", fx=0.7, fy=0.7):
    doc = page.Document
    d, x = ORIENT[orientation]
    v = doc.addObject("TechDraw::DrawViewPart", "View")
    page.addView(v)
    v.Source = [source]
    v.Direction = App.Vector(*d)
    v.XDirection = App.Vector(*x)
    try:
        v.ScaleType = "Page"
    except Exception:
        pass
    v.Label = "Drawing View%d" % (len([o for o in page.Views]) or 1)
    _place(page, v, fx, fy)
    doc.recompute()
    return v


def model_sources():
    """(label, object) of open parts/assemblies that can be shown on a sheet."""
    from .replace import main_object
    out = []
    for n in App.listDocuments():
        d = App.getDocument(n)
        if any(o.isDerivedFrom("TechDraw::DrawPage") for o in d.Objects):
            continue
        o = main_object(d)
        if o is not None:
            out.append((d.Label, o))
    return out


# ------------------------------------------------------------------ commands
def _ensure_page():
    from . import naming
    p = page_of()
    if p is None:
        naming.new_document("drawing")
        p = page_of()
    return p


def _choose_source(title):
    import FreeCADGui as Gui
    from PySide import QtWidgets
    srcs = model_sources()
    sel = [o for o in Gui.Selection.getSelection() if not o.isDerivedFrom("TechDraw::DrawView")]
    if sel:
        return sel[0]
    if not srcs:
        QtWidgets.QMessageBox.information(Gui.getMainWindow(), title, "Open the part or assembly you want to show first.")
        return None
    if len(srcs) == 1:
        return srcs[0][1]
    lab, ok = QtWidgets.QInputDialog.getItem(Gui.getMainWindow(), title, "Part/Assembly to Insert:", [s[0] for s in srcs], 0, False)
    return dict(srcs).get(lab) if ok else None


def cmd_standard_3view():
    src = _choose_source("Standard 3 View")
    if src is None:
        return
    page = _ensure_page()
    page.Document.openTransaction("Standard 3 View")
    standard_3view(page, src)
    page.Document.commitTransaction()


def cmd_model_view():
    import FreeCADGui as Gui
    from PySide import QtWidgets
    src = _choose_source("Model View")
    if src is None:
        return
    o, ok = QtWidgets.QInputDialog.getItem(Gui.getMainWindow(), "Model View", "Orientation:", list(ORIENT), 6, False)
    if not ok:
        return
    page = _ensure_page()
    page.Document.openTransaction("Model View")
    model_view(page, src, o)
    page.Document.commitTransaction()


# ------------------------------------------------------------------ annotations (P20)
def _view_axes(v):
    d = App.Vector(v.Direction)
    d.normalize()
    x = App.Vector(v.XDirection)
    if x.Length < 1e-9:
        x = App.Vector(1, 0, 0)
    x.normalize()
    y = d.cross(x)
    return d, x, y


def _view_edges(v):
    out = []
    i = 0
    while True:
        try:
            e = v.getEdgeBySelection("Edge%d" % i)
        except Exception:
            break
        if e is None:
            break
        out.append(("Edge%d" % i, e))
        i += 1
        if i > 5000:
            break
    return out


def _sketch_dims(body):
    """[(kind, value mm, 3D direction or None, sketch)] for driving dimensions of the body's sketches."""
    out = []
    for o in body.Group if hasattr(body, "Group") else []:
        if not o.isDerivedFrom("Sketcher::SketchObject"):
            continue
        plc = o.getGlobalPlacement()
        rot = plc.Rotation
        for c in o.Constraints:
            if not c.Driving or c.Type not in ("Distance", "DistanceX", "DistanceY", "Radius", "Diameter"):
                continue
            val = float(c.Value)
            if c.Type in ("Radius", "Diameter"):
                out.append((c.Type, val, None, o))
                continue
            if c.Type == "DistanceX":
                d3 = rot.multVec(App.Vector(1, 0, 0))
            elif c.Type == "DistanceY":
                d3 = rot.multVec(App.Vector(0, 1, 0))
            elif c.Second == -2000:                                 # length of one line
                g = o.Geometry[c.First] if 0 <= c.First < len(o.Geometry) else None
                d3 = rot.multVec(g.EndPoint - g.StartPoint) if g is not None and hasattr(g, "StartPoint") else None
            else:                                                   # point to point
                try:
                    d3 = rot.multVec(o.getPoint(c.Second, c.SecondPos) - o.getPoint(c.First, c.FirstPos))
                except Exception:
                    d3 = None
            out.append((c.Type, abs(val), d3, o))
    return out


def model_items(view):
    """SOLIDWORKS Insert Model Items (dimensions from the sketches) for one drawing view.
    Each sketch dimension whose sketch is parallel to the view becomes a drawing dimension on a
    view edge of the same length and direction (circles: same radius). Returns the dimensions made."""
    src = (getattr(view, "Source", None) or [None])[0]
    if src is None:
        return []
    page = view.findParentPage() if hasattr(view, "findParentPage") else None
    if page is None:
        pages = [p for p in view.InList if p.isDerivedFrom("TechDraw::DrawPage")]
        page = pages[0] if pages else None
    from . import materials
    bodies = materials._bodies_in(src) or [src]
    d, vx, vy = _view_axes(view)
    sc = float(view.getScale()) if hasattr(view, "getScale") else float(view.Scale)
    edges = _view_edges(view)
    used = set()
    made = []
    doc = view.Document
    tol = 1e-3 * max(1.0, sc)
    for body in bodies:
        for kind, val, d3, sk in _sketch_dims(body):
            n = sk.getGlobalPlacement().Rotation.multVec(App.Vector(0, 0, 1))
            if abs(abs(n.dot(d)) - 1.0) > 1e-6:
                continue                                   # sketch not parallel to this view
            target, typ = None, None
            if kind in ("Radius", "Diameter"):
                r = val if kind == "Radius" else val / 2.0
                for name, e in edges:
                    c = getattr(e, "Curve", None)
                    if name not in used and c is not None and hasattr(c, "Radius") and abs(c.Radius - r * sc) < tol:
                        target, typ = name, kind
                        break
            elif d3 is not None:
                horiz = abs(d3.dot(vx)) > abs(d3.dot(vy))
                for name, e in edges:
                    import Part
                    if name in used or len(e.Vertexes) != 2 or not isinstance(e.Curve, (Part.Line, Part.LineSegment)):
                        continue
                    p, q = e.Vertexes[0].Point, e.Vertexes[1].Point
                    dx, dy = abs(q.x - p.x), abs(q.y - p.y)
                    if horiz and dy < tol and abs(dx - val * sc) < tol:
                        target, typ = name, "DistanceX"
                    elif not horiz and dx < tol and abs(dy - val * sc) < tol:
                        target, typ = name, "DistanceY"
                    if target:
                        break
            if target is None:
                continue
            used.add(target)
            dim = doc.addObject("TechDraw::DrawViewDimension", "Dimension")
            dim.Type = typ
            dim.References2D = [(view, target)]
            try:
                dim.MeasureType = "Projected"
            except Exception:
                pass
            if page is not None:
                page.addView(dim)
            made.append(dim)
    doc.recompute()
    return made


def set_display_style(views, style):
    """SOLIDWORKS view Display Style: 'hlr' Hidden Lines Removed, 'hlv' Hidden Lines Visible,
    'tangent' toggles tangent edges visible."""
    for v in views:
        if style == "hlr":
            v.HardHidden = False
            v.SmoothHidden = False
        elif style == "hlv":
            v.HardHidden = True
        elif style == "tangent_on":
            v.SmoothVisible = True
        elif style == "tangent_off":
            v.SmoothVisible = False
    if views:
        views[0].Document.recompute()


def _selected_views():
    import FreeCADGui as Gui
    vs = [o for o in Gui.Selection.getSelection() if o.isDerivedFrom("TechDraw::DrawViewPart")]
    if vs:
        return vs
    p = page_of()
    return [o for o in (p.Views if p else []) if o.isDerivedFrom("TechDraw::DrawViewPart")]


def cmd_model_items():
    vs = _selected_views()
    if not vs:
        return
    doc = vs[0].Document
    doc.openTransaction("Model Items")
    n = sum(len(model_items(v)) for v in vs)
    doc.commitTransaction()
    try:
        import FreeCADGui as Gui
        Gui.getMainWindow().statusBar().showMessage("Model Items: %d dimension(s) inserted" % n, 5000)
    except Exception:
        pass


def cmd_display_style(style):
    def go():
        vs = _selected_views()
        if vs:
            vs[0].Document.openTransaction("Display Style")
            set_display_style(vs, style)
            vs[0].Document.commitTransaction()
    return go
